namespace AiDotNet.Generators;

/// <summary>
/// Existing violations of the <see cref="OptionsFidelityAnalyzer"/> rules when they became errors
/// (2026-10-30). Each set may only shrink: an entry that stops violating is an ADNOPT005 error.
/// </summary>
/// <remarks>
/// <para>
/// <see cref="UnreadOptions"/> also drives the generated option-sensitivity tests: a property listed
/// here is statically known to change nothing, so its generated test is emitted as skipped with an
/// ADNOPT001 reason instead of failing at run time. Fixing the property (reading it) makes this entry
/// stale, its removal re-enables the runtime test, and that test then has to pass.
/// </para>
/// </remarks>
internal static class OptionsFidelityBaselines
{
